import {
  type ChordTones,
  type FretShape,
  GUITAR_TUNING,
  UKULELE_TUNING,
  generateShapes,
  shapeMatches,
} from "@acordia/chord-engine";

/**
 * Chord fingerings for fretted instruments, from the open chords-db library
 * (MIT, github.com/tombatossals/chords-db), with shapes generated by the
 * chord engine for chords it does not cover. The library is only downloaded
 * when someone picks guitar or ukulele.
 */

export type FrettedInstrument = "guitar" | "ukulele";

export const TUNINGS: Record<FrettedInstrument, readonly number[]> = {
  guitar: GUITAR_TUNING,
  ukulele: UKULELE_TUNING,
};

export const STRING_NAMES: Record<FrettedInstrument, readonly string[]> = {
  guitar: ["E", "A", "D", "G", "B", "E"],
  ukulele: ["G", "C", "E", "A"],
};

/** Re-entrant ukulele tuning has no fixed lowest string, so its bass is free. */
const CHECK_BASS: Record<FrettedInstrument, boolean> = { guitar: true, ukulele: false };

interface LibraryPosition {
  readonly frets: readonly number[];
  readonly fingers: readonly number[];
  readonly baseFret: number;
  readonly barres: readonly number[];
}

interface Library {
  readonly chords: Record<string, readonly { readonly positions: readonly LibraryPosition[] }[]>;
}

const loaders: Record<FrettedInstrument, () => Promise<{ default: unknown }>> = {
  guitar: () => import("@tombatossals/chords-db/lib/guitar.json"),
  ukulele: () => import("@tombatossals/chords-db/lib/ukulele.json"),
};

const cache = new Map<FrettedInstrument, Promise<FretShape[]>>();

/** Every shape in the library, with frets made absolute. Loaded once. */
export function loadLibrary(instrument: FrettedInstrument): Promise<FretShape[]> {
  let pending = cache.get(instrument);
  if (!pending) {
    pending = loaders[instrument]().then(({ default: data }) => flatten(data as Library));
    cache.set(instrument, pending);
  }
  return pending;
}

function flatten(library: Library): FretShape[] {
  const shapes: FretShape[] = [];
  for (const group of Object.values(library.chords)) {
    for (const chord of group) {
      for (const p of chord.positions) {
        // Library frets count from baseFret (1 = baseFret); 0 is open, -1 muted.
        const absolute = (fret: number) => (fret > 0 ? fret + p.baseFret - 1 : fret);
        shapes.push({ frets: p.frets.map(absolute), fingers: p.fingers, barres: p.barres.map(absolute) });
      }
    }
  }
  return shapes;
}

/**
 * Shapes that play this chord: library shapes first, lowest on the neck
 * first; generated ones when the library has none.
 */
export function findShapes(chord: ChordTones, library: readonly FretShape[], instrument: FrettedInstrument): FretShape[] {
  const tuning = TUNINGS[instrument];
  const checkBass = CHECK_BASS[instrument];
  const seen = new Set<string>();
  const matches = library.filter((shape) => {
    const key = shape.frets.join(",");
    if (seen.has(key) || !shapeMatches(shape, chord, tuning, checkBass)) return false;
    seen.add(key);
    return true;
  });
  if (matches.length > 0) return matches.sort((a, b) => lowestFret(a) - lowestFret(b));
  return generateShapes(chord, tuning, { checkBass });
}

function lowestFret(shape: FretShape): number {
  const fretted = shape.frets.filter((f) => f > 0);
  return fretted.length > 0 ? Math.min(...fretted) : 0;
}
